1	package shadow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io/fs"
8		"os"
9		"path/filepath"
10		"sync"
11		"time"
12	)
13	
14	const storeFileName = "shadow-store.json"
15	const storeFormat = 1
16	
17	// View 是设备影子当前状态的只读快照。
18	type View struct {
19		DeviceID string
20		// Version 是设备当前版本（登记时的初始版本，随有效上报更新）。
21		Version string
22		// Online 表示设备是否在线。新登记设备离线，有效上报置为在线。
23		Online bool
24		// Revision 是当前期望配置的修订号，从零开始，每次成功修改加一。
25		Revision uint64
26		// Desired 是期望配置的完整 JSON 对象。
27		Desired json.RawMessage
28		// Reported 是上报配置的完整 JSON 对象。
29		Reported json.RawMessage
30		// LastSeq 是最后接受的上报序号。
31		LastSeq uint64
32	}
33	
34	// AuditRecord 是一次成功修改期望配置的审计记录。
35	type AuditRecord struct {
36		DeviceID string
37		Operator string
38		Time     time.Time
39		// Revision 是本次修改产生的新修订号。
40		Revision uint64
41		// RequestID 是产生本次修改的批量请求标识；单设备修改为空。
42		RequestID string
43		// Before 是修改前的完整期望配置。
44		Before json.RawMessage
45		// After 是修改后的完整期望配置。
46		After json.RawMessage
47	}
48	
49	// deviceState 是单台设备的内部状态。
50	type deviceState struct {
51		Version        string
52		Online         bool
53		Revision       uint64
54		Desired        json.RawMessage
55		Reported       json.RawMessage
56		LastSeq        uint64
57		LastReportTime time.Time
58		// DiffSince 记录每条差异路径首次出现的时间。
59		DiffSince map[string]time.Time
60		Audit     []AuditRecord
61	}
62	
63	// refreshDiff 重新计算差异路径：已有路径保留原时间，新路径使用 t，消失的路径移除。
64	func (d *deviceState) refreshDiff(t time.Time) {
65		entries := computeDiff(d.Desired, d.Reported)
66		next := make(map[string]time.Time, len(entries))
67		for _, e := range entries {
68			if since, ok := d.DiffSince[e.Path]; ok {
69				next[e.Path] = since
70			} else {
71				next[e.Path] = t
72			}
73		}
74		d.DiffSince = next
75	}
76	
77	// Store 是本地设备影子存储，所有状态与审计记录保存在指定目录。
78	// Store 可安全并发使用。
79	type Store struct {
80		mu        sync.Mutex
81		dir       string
82		closed    bool
83		devices   map[string]*deviceState
84		versions  map[string]*versionState
85		campaigns map[string]*campaignState
86		batches   map[string]*batchRequestState
87	}
88	
89	// Open 打开（必要时创建）位于 dir 的本地影子存储。
90	// 已有内容损坏或格式不识别时返回 ErrCorruptStorage，不会按空数据覆盖。
91	func Open(dir string) (*Store, error) {
92		if err := os.MkdirAll(dir, 0o755); err != nil {
93			return nil, fmt.Errorf("shadow: create store dir: %w", err)
94		}
95		s := &Store{
96			dir:       dir,
97			devices:   map[string]*deviceState{},
98			versions:  map[string]*versionState{},
99			campaigns: map[string]*campaignState{},
100			batches:   map[string]*batchRequestState{},
101		}
102		data, err := os.ReadFile(s.filePath())
103		if errors.Is(err, fs.ErrNotExist) {
104			return s, nil
105		}
106		if err != nil {
107			return nil, fmt.Errorf("shadow: read store: %w", err)
108		}
109		if err := s.restore(data); err != nil {
110			return nil, err
111		}
112		return s, nil
113	}
114	
115	// Close 关闭存储。关闭后的操作返回 ErrClosed。
116	func (s *Store) Close() error {
117		s.mu.Lock()
118		defer s.mu.Unlock()
119		if s.closed {
120			return ErrClosed
121		}
122		s.closed = true
123		return nil
124	}
125	
126	// Register 登记一台模拟设备。设备标识和初始版本不能为空；
127	// 重复登记返回 ErrDeviceExists。新设备初始离线，双方配置均为空对象。
128	func (s *Store) Register(deviceID, version string) error {
129		s.mu.Lock()
130		defer s.mu.Unlock()
131		if err := s.checkOpen(); err != nil {
132			return err
133		}
134		if deviceID == "" {
135			return ErrInvalidDeviceID
136		}
137		if version == "" {
138			return ErrInvalidVersion
139		}
140		if _, ok := s.devices[deviceID]; ok {
141			return fmt.Errorf("%w: %s", ErrDeviceExists, deviceID)
142		}
143		return s.commit(func() error {
144			s.devices[deviceID] = &deviceState{
145				Version:   version,
146				Desired:   json.RawMessage(`{}`),
147				Reported:  json.RawMessage(`{}`),
148				DiffSince: map[string]time.Time{},
149			}
150			return nil
151		})
152	}
153	
154	// UpdateDesired 修改设备的期望配置，完整替换旧配置。
155	// 需携带操作者、操作时间和已读取的期望修订号；修订号不等于当前值时
156	// 返回 ErrRevisionConflict，影子和审计均不改变。成功时返回新修订号。
157	func (s *Store) UpdateDesired(deviceID, operator string, at time.Time, revision uint64, config json.RawMessage) (uint64, error) {
158		s.mu.Lock()
159		defer s.mu.Unlock()
160		if err := s.checkOpen(); err != nil {
161			return 0, err
162		}
163		d, err := s.lookup(deviceID)
164		if err != nil {
165			return 0, err
166		}
167		if operator == "" {
168			return 0, ErrInvalidOperator
169		}
170		if at.IsZero() {
171			return 0, ErrInvalidTime
172		}
173		cfg, err := validateConfig(config)
174		if err != nil {
175			return 0, err
176		}
177		if revision != d.Revision {
178			return 0, fmt.Errorf("%w: want %d, got %d", ErrRevisionConflict, d.Revision, revision)
179		}
180		var newRevision uint64
181		err = s.commit(func() error {
182			before := d.Desired
183			d.Desired = cfg
184			d.Revision++
185			newRevision = d.Revision
186			d.Audit = append(d.Audit, AuditRecord{
187				DeviceID: deviceID,
188				Operator: operator,
189				Time:     at,
190				Revision: newRevision,
191				Before:   cloneRaw(before),
192				After:    cloneRaw(cfg),
193			})
194			d.refreshDiff(at)
195			return nil
196		})
197		if err != nil {
198			return 0, err
199		}
200		return newRevision, nil
201	}
202	
203	// Report 处理设备上报。需携带正整数序号、时间、非空当前版本和完整配置。
204	// 更大序号更新上报并标为在线；相同序号且版本、配置、时间相同视为重复，
205	// 成功返回但不改变状态；相同序号内容不同或更小序号返回错误。
206	//
207	// 校验、序号判断与影子写入规则与安装/回滚成功的附带上报共用同一实现
208	// （checkReport/applyReport），仅错误类别保持各自公开的哨兵不变。
209	func (s *Store) Report(deviceID string, seq uint64, at time.Time, version string, config json.RawMessage) error {
210		s.mu.Lock()
211		defer s.mu.Unlock()
212		if err := s.checkOpen(); err != nil {
213			return err
214		}
215		d, err := s.lookup(deviceID)
216		if err != nil {
217			return err
218		}
219		in := reportInput{DeviceID: deviceID, Seq: seq, At: at, Version: version, Config: config}
220		cfg, verdict, err := checkReport(d, in, "")
221		if err != nil {
222			return reportPlainError(err.(errBadReport))
223		}
224		if verdict == reportDuplicate {
225			// 重复上报：成功返回，不写入影子，也不触发持久化。
226			return nil
227		}
228		return s.commit(func() error {
229			applyReport(d, in, cfg, verdict, at)
230			return nil
231		})
232	}
233	
234	// SetOffline 将设备标为离线。只改变在线状态，保留版本及双方配置。
235	func (s *Store) SetOffline(deviceID string) error {
236		s.mu.Lock()
237		defer s.mu.Unlock()
238		if err := s.checkOpen(); err != nil {
239			return err
240		}
241		d, err := s.lookup(deviceID)
242		if err != nil {
243			return err
244		}
245		return s.commit(func() error {
246			d.Online = false
247			return nil
248		})
249	}
250	
251	// Get 返回设备影子当前状态的快照。返回的数据是独立副本，
252	// 调用方修改不影响已保存的记录。
253	func (s *Store) Get(deviceID string) (View, error) {
254		s.mu.Lock()
255		defer s.mu.Unlock()
256		if err := s.checkOpen(); err != nil {
257			return View{}, err
258		}
259		d, err := s.lookup(deviceID)
260		if err != nil {
261			return View{}, err
262		}
263		return View{
264			DeviceID: deviceID,
265			Version:  d.Version,
266			Online:   d.Online,
267			Revision: d.Revision,
268			Desired:  cloneRaw(d.Desired),
269			Reported: cloneRaw(d.Reported),
270			LastSeq:  d.LastSeq,
271		}, nil
272	}
273	
274	// Diff 返回期望配置与上报配置之间的差异，按 JSON Pointer 路径字典序排列。
275	func (s *Store) Diff(deviceID string) ([]DiffEntry, error) {
276		s.mu.Lock()
277		defer s.mu.Unlock()
278		if err := s.checkOpen(); err != nil {
279			return nil, err
280		}
281		d, err := s.lookup(deviceID)
282		if err != nil {
283			return nil, err
284		}
285		entries := computeDiff(d.Desired, d.Reported)
286		for i := range entries {
287			entries[i].Since = d.DiffSince[entries[i].Path]
288		}
289		return entries, nil
290	}
291	
292	// Audit 按修订号递增返回设备的审计记录。返回的数据是独立副本。
293	func (s *Store) Audit(deviceID string) ([]AuditRecord, error) {
294		s.mu.Lock()
295		defer s.mu.Unlock()
296		if err := s.checkOpen(); err != nil {
297			return nil, err
298		}
299		d, err := s.lookup(deviceID)
300		if err != nil {
301			return nil, err
302		}
303		out := make([]AuditRecord, len(d.Audit))
304		for i, rec := range d.Audit {
305			out[i] = rec
306			out[i].Before = cloneRaw(rec.Before)
307			out[i].After = cloneRaw(rec.After)
308		}
309		return out, nil
310	}
311	
312	func (s *Store) checkOpen() error {
313		if s.closed {
314			return ErrClosed
315		}
316		return nil
317	}
318	
319	func (s *Store) lookup(deviceID string) (*deviceState, error) {
320		if deviceID == "" {
321			return nil, ErrInvalidDeviceID
322		}
323		d, ok := s.devices[deviceID]
324		if !ok {
325			return nil, fmt.Errorf("%w: %s", ErrDeviceNotFound, deviceID)
326		}
327		return d, nil
328	}
329	
330	// commit 执行一次状态修改并持久化。保存失败时回滚内存状态并返回错误，
331	// 保证一次操作涉及的状态与审计一起保存、查询仍显示操作前的结果。
332	// 调用时必须持有 s.mu。
333	func (s *Store) commit(mutate func() error) error {
334		snapshot, err := s.marshal()
335		if err != nil {
336			return err
337		}
338		if err := mutate(); err != nil {
339			return err
340		}
341		if err := s.persist(); err != nil {
342			// 回滚内存状态；snapshot 由本进程序列化，恢复不应失败。
343			_ = s.restore(snapshot)
344			return err
345		}
346		return nil
347	}
348	
349	func (s *Store) filePath() string {
350		return filepath.Join(s.dir, storeFileName)
351	}
352	
353	// persist 把当前状态原子写入存储文件。
354	func (s *Store) persist() error {
355		data, err := s.marshal()
356		if err != nil {
357			return err
358		}
359		tmp, err := os.CreateTemp(s.dir, ".shadow-store-*.tmp")
360		if err != nil {
361			return fmt.Errorf("shadow: save store: %w", err)
362		}
363		tmpName := tmp.Name()
364		if _, err := tmp.Write(data); err != nil {
365			tmp.Close()
366			os.Remove(tmpName)
367			return fmt.Errorf("shadow: save store: %w", err)
368		}
369		if err := tmp.Sync(); err != nil {
370			tmp.Close()
371			os.Remove(tmpName)
372			return fmt.Errorf("shadow: save store: %w", err)
373		}
374		if err := tmp.Close(); err != nil {
375			os.Remove(tmpName)
376			return fmt.Errorf("shadow: save store: %w", err)
377		}
378		if err := os.Rename(tmpName, s.filePath()); err != nil {
379			os.Remove(tmpName)
380			return fmt.Errorf("shadow: save store: %w", err)
381		}
382		return nil
383	}
384	
385	// diskStore 是存储文件的磁盘格式。
386	type diskStore struct {
387		Format    int                     `json:"format"`
388		Devices   map[string]diskState    `json:"devices"`
389		Versions  map[string]diskVersion  `json:"versions,omitempty"`
390		Campaigns map[string]diskCampaign `json:"campaigns,omitempty"`
391		Batches   map[string]diskBatch    `json:"batches,omitempty"`
392	}
393	
394	type diskState struct {
395		Version        string               `json:"version"`
396		Online         bool                 `json:"online"`
397		Revision       uint64               `json:"revision"`
398		Desired        json.RawMessage      `json:"desired"`
399		Reported       json.RawMessage      `json:"reported"`
400		LastSeq        uint64               `json:"lastSeq"`
401		LastReportTime time.Time            `json:"lastReportTime,omitempty"`
402		DiffSince      map[string]time.Time `json:"diffSince,omitempty"`
403		Audit          []diskAudit          `json:"audit,omitempty"`
404	}
405	
406	type diskAudit struct {
407		Operator  string          `json:"operator"`
408		Time      time.Time       `json:"time"`
409		Revision  uint64          `json:"revision"`
410		RequestID string          `json:"requestId,omitempty"`
411		Before    json.RawMessage `json:"before"`
412		After     json.RawMessage `json:"after"`
413	}
414	
415	func (s *Store) marshal() ([]byte, error) {
416		disk := diskStore{Format: storeFormat, Devices: make(map[string]diskState, len(s.devices))}
417		for id, d := range s.devices {
418			ds := diskState{
419				Version:        d.Version,
420				Online:         d.Online,
421				Revision:       d.Revision,
422				Desired:        cloneRaw(d.Desired),
423				Reported:       cloneRaw(d.Reported),
424				LastSeq:        d.LastSeq,
425				LastReportTime: d.LastReportTime,
426				DiffSince:      make(map[string]time.Time, len(d.DiffSince)),
427			}
428			for p, t := range d.DiffSince {
429				ds.DiffSince[p] = t
430			}
431			for _, rec := range d.Audit {
432				ds.Audit = append(ds.Audit, diskAudit{
433					Operator:  rec.Operator,
434					Time:      rec.Time,
435					Revision:  rec.Revision,
436					RequestID: rec.RequestID,
437					Before:    cloneRaw(rec.Before),
438					After:     cloneRaw(rec.After),
439				})
440			}
441			disk.Devices[id] = ds
442		}
443		disk.Versions = s.marshalVersions()
444		campaigns, err := s.marshalCampaigns()
445		if err != nil {
446			return nil, err
447		}
448		disk.Campaigns = campaigns
449		disk.Batches = s.marshalBatches()
450		data, err := json.Marshal(disk)
451		if err != nil {
452			return nil, fmt.Errorf("shadow: encode store: %w", err)
453		}
454		return data, nil
455	}
456	
457	// restore 从存储文件内容恢复状态。内容损坏或格式不识别时返回
458	// ErrCorruptStorage，绝不按空数据覆盖。
459	func (s *Store) restore(data []byte) error {
460		var disk diskStore
461		if err := json.Unmarshal(data, &disk); err != nil {
462			return fmt.Errorf("%w: %v", ErrCorruptStorage, err)
463		}
464		if disk.Format != storeFormat {
465			return fmt.Errorf("%w: unsupported format %d", ErrCorruptStorage, disk.Format)
466		}
467		devices := make(map[string]*deviceState, len(disk.Devices))
468		for id, ds := range disk.Devices {
469			if id == "" {
470				return fmt.Errorf("%w: empty device id", ErrCorruptStorage)
471			}
472			if _, ok := decodeObject(ds.Desired); !ok {
473				return fmt.Errorf("%w: device %s desired config invalid", ErrCorruptStorage, id)
474			}
475			if _, ok := decodeObject(ds.Reported); !ok {
476				return fmt.Errorf("%w: device %s reported config invalid", ErrCorruptStorage, id)
477			}
478			d := &deviceState{
479				Version:        ds.Version,
480				Online:         ds.Online,
481				Revision:       ds.Revision,
482				Desired:        cloneRaw(ds.Desired),
483				Reported:       cloneRaw(ds.Reported),
484				LastSeq:        ds.LastSeq,
485				LastReportTime: ds.LastReportTime,
486				DiffSince:      make(map[string]time.Time, len(ds.DiffSince)),
487			}
488			for p, t := range ds.DiffSince {
489				d.DiffSince[p] = t
490			}
491			for _, da := range ds.Audit {
492				if da.Operator == "" || da.Time.IsZero() || da.Revision == 0 {
493					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
494				}
495				if _, ok := decodeObject(da.Before); !ok {
496					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
497				}
498				if _, ok := decodeObject(da.After); !ok {
499					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
500				}
501				d.Audit = append(d.Audit, AuditRecord{
502					DeviceID:  id,
503					Operator:  da.Operator,
504					Time:      da.Time,
505					Revision:  da.Revision,
506					RequestID: da.RequestID,
507					Before:    cloneRaw(da.Before),
508					After:     cloneRaw(da.After),
509				})
510			}
511			// 审计必须能完整解释当前期望配置：修订号从 1 开始逐条连续到当前
512			// 修订号；首条修改前是登记时的空对象，每条修改后等于下一条修改前，
513			// 末条修改后等于当前期望配置。比较沿用配置的 JSON 语义，不要求
514			// 操作时间严格递增。修订号为 0 时审计必须为空、期望必须为空对象。
515			if uint64(len(d.Audit)) != d.Revision {
516				return fmt.Errorf("%w: device %s audit history does not cover revision %d",
517					ErrCorruptStorage, id, d.Revision)
518			}
519			expected := json.RawMessage(`{}`)
520			for i, rec := range d.Audit {
521				if rec.Revision != uint64(i+1) {
522					return fmt.Errorf("%w: device %s audit revision %d out of sequence",
523						ErrCorruptStorage, id, rec.Revision)
524				}
525				if !rawEqual(rec.Before, expected) {
526					return fmt.Errorf("%w: device %s audit revision %d broken chain",
527						ErrCorruptStorage, id, rec.Revision)
528				}
529				expected = rec.After
530			}
531			if !rawEqual(expected, d.Desired) {
532				return fmt.Errorf("%w: device %s desired config not explained by audit",
533					ErrCorruptStorage, id)
534			}
535			devices[id] = d
536		}
537		s.devices = devices
538		if err := s.restoreVersions(disk.Versions); err != nil {
539			return err
540		}
541		if err := s.restoreCampaigns(disk.Campaigns); err != nil {
542			return err
543		}
544		if err := s.restoreBatches(disk.Batches); err != nil {
545			return err
546		}
547		return nil
548	}
549

