1	package shadow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"sync"
9		"testing"
10		"time"
11	)
12	
13	var base = time.Date(2026, 10, 2, 12, 0, 0, 0, time.UTC)
14	
15	func openTemp(t *testing.T) (*Store, string) {
16		t.Helper()
17		dir := t.TempDir()
18		s, err := Open(dir)
19		if err != nil {
20			t.Fatalf("Open: %v", err)
21		}
22		t.Cleanup(func() { s.Close() })
23		return s, dir
24	}
25	
26	func mustRegister(t *testing.T, s *Store, id, version string) {
27		t.Helper()
28		if err := s.Register(id, version); err != nil {
29			t.Fatalf("Register(%s): %v", id, err)
30		}
31	}
32	
33	func TestRegisterValidation(t *testing.T) {
34		s, _ := openTemp(t)
35		if err := s.Register("", "1.0"); !errors.Is(err, ErrInvalidDeviceID) {
36			t.Fatalf("empty id: got %v", err)
37		}
38		if err := s.Register("dev-1", ""); !errors.Is(err, ErrInvalidVersion) {
39			t.Fatalf("empty version: got %v", err)
40		}
41		mustRegister(t, s, "dev-1", "1.0")
42		if err := s.Register("dev-1", "2.0"); !errors.Is(err, ErrDeviceExists) {
43			t.Fatalf("duplicate: got %v", err)
44		}
45		// 重复登记不覆盖原记录
46		v, err := s.Get("dev-1")
47		if err != nil {
48			t.Fatal(err)
49		}
50		if v.Version != "1.0" {
51			t.Fatalf("version overwritten: %s", v.Version)
52		}
53		// 新设备初始离线，双方配置为空对象
54		if v.Online {
55			t.Fatal("new device should be offline")
56		}
57		if string(v.Desired) != "{}" || string(v.Reported) != "{}" {
58			t.Fatalf("initial configs: desired=%s reported=%s", v.Desired, v.Reported)
59		}
60		if v.Revision != 0 || v.LastSeq != 0 {
61			t.Fatalf("initial revision/seq: %d/%d", v.Revision, v.LastSeq)
62		}
63	}
64	
65	func TestUnregisteredDevice(t *testing.T) {
66		s, _ := openTemp(t)
67		if _, err := s.Get("ghost"); !errors.Is(err, ErrDeviceNotFound) {
68			t.Fatalf("Get: %v", err)
69		}
70		if _, err := s.UpdateDesired("ghost", "op", base, 0, json.RawMessage(`{}`)); !errors.Is(err, ErrDeviceNotFound) {
71			t.Fatalf("UpdateDesired: %v", err)
72		}
73		if err := s.Report("ghost", 1, base, "1.0", json.RawMessage(`{}`)); !errors.Is(err, ErrDeviceNotFound) {
74			t.Fatalf("Report: %v", err)
75		}
76		if err := s.SetOffline("ghost"); !errors.Is(err, ErrDeviceNotFound) {
77			t.Fatalf("SetOffline: %v", err)
78		}
79		if _, err := s.Diff("ghost"); !errors.Is(err, ErrDeviceNotFound) {
80			t.Fatalf("Diff: %v", err)
81		}
82		if _, err := s.Audit("ghost"); !errors.Is(err, ErrDeviceNotFound) {
83			t.Fatalf("Audit: %v", err)
84		}
85	}
86	
87	func TestUpdateDesiredAndRevision(t *testing.T) {
88		s, _ := openTemp(t)
89		mustRegister(t, s, "dev-1", "1.0")
90	
91		// 操作者为空、时间缺失、配置无效：报错且不改状态
92		if _, err := s.UpdateDesired("dev-1", "", base, 0, json.RawMessage(`{}`)); !errors.Is(err, ErrInvalidOperator) {
93			t.Fatalf("empty operator: %v", err)
94		}
95		if _, err := s.UpdateDesired("dev-1", "op", time.Time{}, 0, json.RawMessage(`{}`)); !errors.Is(err, ErrInvalidTime) {
96			t.Fatalf("zero time: %v", err)
97		}
98		for _, bad := range []string{`[1,2]`, `"str"`, `42`, `null`, `{broken`, ``} {
99			if _, err := s.UpdateDesired("dev-1", "op", base, 0, json.RawMessage(bad)); !errors.Is(err, ErrInvalidConfig) {
100				t.Fatalf("config %q: %v", bad, err)
101			}
102		}
103		v, _ := s.Get("dev-1")
104		if v.Revision != 0 || string(v.Desired) != "{}" {
105			t.Fatalf("state changed by invalid updates: %+v", v)
106		}
107	
108		// 修订号冲突：影子和审计均不改变
109		if _, err := s.UpdateDesired("dev-1", "op", base, 5, json.RawMessage(`{"a":1}`)); !errors.Is(err, ErrRevisionConflict) {
110			t.Fatalf("conflict: %v", err)
111		}
112		v, _ = s.Get("dev-1")
113		if v.Revision != 0 || string(v.Desired) != "{}" {
114			t.Fatalf("state changed by conflict: %+v", v)
115		}
116		if recs, _ := s.Audit("dev-1"); len(recs) != 0 {
117			t.Fatalf("audit changed by conflict: %v", recs)
118		}
119	
120		// 成功修改，修订号从 1 开始
121		rev, err := s.UpdateDesired("dev-1", "alice", base, 0, json.RawMessage(`{"a":1}`))
122		if err != nil || rev != 1 {
123			t.Fatalf("update: rev=%d err=%v", rev, err)
124		}
125		// 提交相同配置也增加修订号
126		rev, err = s.UpdateDesired("dev-1", "bob", base.Add(time.Minute), 1, json.RawMessage(`{"a":1}`))
127		if err != nil || rev != 2 {
128			t.Fatalf("same config update: rev=%d err=%v", rev, err)
129		}
130	
131		// 审计按修订号递增，含前后完整配置
132		recs, err := s.Audit("dev-1")
133		if err != nil || len(recs) != 2 {
134			t.Fatalf("audit: %v %v", recs, err)
135		}
136		if recs[0].Revision != 1 || recs[1].Revision != 2 {
