247	func TestDiffSemantics(t *testing.T) {
248		s, _ := openTemp(t)
249		mustRegister(t, s, "dev-1", "1.0")
250		t1 := base
251		if _, err := s.UpdateDesired("dev-1", "op", t1, 0, json.RawMessage(`{
252			"wifi": {"ssid": "a", "chan": 6},
253			"nullField": null,
254			"arr": [1, 2],
255			"onlyDesired": {"deep": true},
256			"num": 1
257		}`)); err != nil {
258			t.Fatal(err)
259		}
260		t2 := base.Add(time.Minute)
261		if err := s.Report("dev-1", 1, t2, "1.0", json.RawMessage(`{
262			"wifi": {"ssid": "b", "chan": 6},
263			"arr": [1, 2, 3],
264			"onlyReported": 5,
265			"num": 1.0
266		}`)); err != nil {
267			t.Fatal(err)
268		}
269		diffs, err := s.Diff("dev-1")
270		if err != nil {
271			t.Fatal(err)
272		}
273		// 期望路径（字典序）：
274		//   /arr          数组整体比较
275		//   /nullField    null 与不存在不同
276		//   /onlyDesired  一侧缺失，只列一条（不下钻）
277		//   /onlyReported 一侧缺失
278		//   /wifi/ssid    逐层比较
279		// num: 1 与 1.0 数值相等，无差异
280		want := []string{"/arr", "/nullField", "/onlyDesired", "/onlyReported", "/wifi/ssid"}
281		if len(diffs) != len(want) {
282			t.Fatalf("diffs: %+v", diffs)
283		}
284		for i, p := range want {
285			if diffs[i].Path != p {
286				t.Fatalf("diff[%d] path: want %s got %s", i, p, diffs[i].Path)
287			}
288		}
289		// 存在性标志
290		if !diffs[0].DesiredExists || !diffs[0].ReportedExists {
291			t.Fatalf("arr exists flags: %+v", diffs[0])
292		}
293		if !diffs[1].DesiredExists || diffs[1].ReportedExists {
294			t.Fatalf("nullField flags: %+v", diffs[1])
295		}
296		if diffs[2].ReportedExists || !diffs[2].DesiredExists {
297			t.Fatalf("onlyDesired flags: %+v", diffs[2])
298		}
299		if diffs[3].DesiredExists || !diffs[3].ReportedExists {
300			t.Fatalf("onlyReported flags: %+v", diffs[3])
301		}
302		// 双方值
303		if string(diffs[4].Desired) != `"a"` || string(diffs[4].Reported) != `"b"` {
304			t.Fatalf("ssid values: %+v", diffs[4])
305		}
306		// 差异时间：/wifi/ssid 等在上报时首次出现
307		for _, d := range diffs {
308			want := t2
309			if d.Path == "/onlyDesired" || d.Path == "/nullField" || d.Path == "/arr" {
310				// 上报前 desired 已有而 reported 为空对象，差异在修改期望时已出现
311				want = t1
312			}
313			if !d.Since.Equal(want) {
314				t.Fatalf("%s since: want %v got %v", d.Path, want, d.Since)
315			}
316		}
317	}
