71	// TestResultHistoryMissingOrExtraRefused 针对“下载成功等待安装、删掉历史仍能打开”
72	// 的问题：缺少、多出、重复或内容矛盾的结果历史都必须拒绝打开整个存储。
73	func TestResultHistoryMissingOrExtraRefused(t *testing.T) {
74		t.Run("history deleted", func(t *testing.T) {
75			s, dir, _ := setupReady(t)
76			defer s.Close()
77			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
78				delete(campaignDoc(doc, "cmp-1"), "results")
79			})
80			assertReopenCorrupt(t, dir, original)
81		})
82		t.Run("history emptied", func(t *testing.T) {
83			_, dir, _ := setupReady(t)
84			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
85				campaignDoc(doc, "cmp-1")["results"] = []any{}
86			})
87			assertReopenCorrupt(t, dir, original)
88		})
89		t.Run("history duplicated", func(t *testing.T) {
90			_, dir, _ := setupReady(t)
91			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
92				rs := resultDocs(doc, "cmp-1")
93				camp := campaignDoc(doc, "cmp-1")
94				camp["results"] = []any{rs[0], rs[0]}
95			})
96			assertReopenCorrupt(t, dir, original)
97		})
98		t.Run("history extra record", func(t *testing.T) {
99			_, dir, _ := setupReady(t)
100			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
101				rs := resultDocs(doc, "cmp-1")
102				extra := map[string]any{
103					"deviceId":    "d1",
104					"operationId": "cmp-1:d1:install",
105					"stage":       "install",
106					"success":     true,
107					"version":     "v2",
108					"at":          "2026-10-02T12:05:00Z",
109				}
110				campaignDoc(doc, "cmp-1")["results"] = []any{rs[0], extra}
111			})
112			assertReopenCorrupt(t, dir, original)
113		})
114		t.Run("success flag contradicted", func(t *testing.T) {
115			_, dir, _ := setupReady(t)
116			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
117				rs := resultDocs(doc, "cmp-1")
118				rs[0]["success"] = false
119				rs[0]["reason"] = "tampered"
120			})
121			assertReopenCorrupt(t, dir, original)
122		})
123		t.Run("time contradicted", func(t *testing.T) {
124			_, dir, _ := setupReady(t)
125			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
126				resultDocs(doc, "cmp-1")[0]["at"] = "2026-10-02T12:09:00Z"
127			})
128			assertReopenCorrupt(t, dir, original)
129		})
130		t.Run("wrong operation id", func(t *testing.T) {
131			_, dir, _ := setupReady(t)
132			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
133				resultDocs(doc, "cmp-1")[0]["operationId"] = "cmp-1:d1:install"
134			})
135			assertReopenCorrupt(t, dir, original)
136		})
137		t.Run("wrong device", func(t *testing.T) {
138			_, dir, _ := setupReady(t)
139			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
140				resultDocs(doc, "cmp-1")[0]["deviceId"] = "ghost"
141			})
142			assertReopenCorrupt(t, dir, original)
143		})
144		t.Run("history out of order", func(t *testing.T) {
145			// 安装成功的设备有两条历史；颠倒顺序即与接受顺序矛盾。
146			_, dir, _ := setupSucceeded(t)
147			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
148				rs := resultDocs(doc, "cmp-1")
149				campaignDoc(doc, "cmp-1")["results"] = []any{rs[1], rs[0]}
150			})
151			assertReopenCorrupt(t, dir, original)
152		})
153		t.Run("install version contradicted", func(t *testing.T) {
154			_, dir, _ := setupSucceeded(t)
155			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
156				resultDocs(doc, "cmp-1")[1]["version"] = "v9"
157			})
158			assertReopenCorrupt(t, dir, original)
159		})
160		t.Run("unexpected version on download", func(t *testing.T) {
161			_, dir, _ := setupReady(t)
162			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
163				resultDocs(doc, "cmp-1")[0]["version"] = "v2"
164			})
165			assertReopenCorrupt(t, dir, original)
166		})
167		t.Run("download record missing on success", func(t *testing.T) {
168			_, dir, _ := setupSucceeded(t)
169			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
170				rs := resultDocs(doc, "cmp-1")
171				campaignDoc(doc, "cmp-1")["results"] = []any{rs[1]}
172			})
173			assertReopenCorrupt(t, dir, original)
174		})
175	}
