177	// setupReady 关闭后返回存储目录，设备处于 ready（下载成功、安装未领取）。
178	func setupReady(t *testing.T) (*Store, string, CampaignSpec) {
179		t.Helper()
180		s := setupUpgrade(t, "d1")
181		spec := upSpec()
182		spec.Devices = []string{"d1"}
183		createCampaign(t, s, spec)
184		bringOnline(t, s, "d1")
185		dl, err := s.Claim(spec.ID, "d1", upBase)
186		if err != nil {
187			t.Fatalf("claim: %v", err)
188		}
189		if err := s.SubmitResult(OperationResult{
190			CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
191			At: upBase.Add(time.Minute), Success: true,
192		}); err != nil {
193			t.Fatalf("download: %v", err)
194		}
195		dir := s.dir
196		if err := s.Close(); err != nil {
197			t.Fatal(err)
198		}
199		return s, dir, spec
200	}
