218	// TestResultHistoryLegitStatesReopen 校验各种合法进度重开后历史与结果保持对应，
219	// 不凭空要求未完成或未执行阶段产生结果。
220	func TestResultHistoryLegitStatesReopen(t *testing.T) {
221		t.Run("download success awaiting install", func(t *testing.T) {
222			_, dir, spec := setupReady(t)
223			s, err := Open(dir)
224			if err != nil {
225				t.Fatalf("ready state must open: %v", err)
226			}
227			defer s.Close()
228			cv, err := s.GetCampaign(spec.ID)
229			if err != nil {
230				t.Fatal(err)
231			}
232			d := findDevice(cv, "d1")
233			if d.Status != DeviceReady || len(cv.Results) != 1 || cv.Results[0].Stage != StageDownload {
234				t.Fatalf("restored ready view: status=%s results=%+v", d.Status, cv.Results)
235			}
236			// 已接受结果的重复提交沿用现有幂等判断，不新增历史。
237			if err := s.SubmitResult(OperationResult{
238				CampaignID: spec.ID, DeviceID: "d1",
239				OperationID: cv.Results[0].OperationID,
240				At:          cv.Results[0].At, Success: true,
241			}); err != nil {
242				t.Fatalf("duplicate replay: %v", err)
243			}
244			if cv2, _ := s.GetCampaign(spec.ID); len(cv2.Results) != 1 {
245				t.Fatalf("replay added history: %+v", cv2.Results)
246			}
247		})
248	
249		t.Run("claim-time download failure kept", func(t *testing.T) {
250			// 首次领取下载时版本已不兼容：下载失败是已有结果，必须保留历史。
251			s := setupUpgrade(t, "d1")
252			spec := upSpec()
253			spec.Devices = []string{"d1"}
254			createCampaign(t, s, spec)
255			if err := s.Report("d1", 1, upBase.Add(-time.Minute), "v3", json.RawMessage(`{}`)); err != nil {
256				t.Fatal(err)
257			}
258			if _, err := s.Claim(spec.ID, "d1", upBase); !errors.Is(err, ErrIncompatibleVersion) {
259				t.Fatalf("want incompatible version, got %v", err)
260			}
261			cv := mustGetCampaign(s, spec.ID)
262			if len(cv.Results) != 1 || cv.Results[0].Success {
263				t.Fatalf("download failure history: %+v", cv.Results)
264			}
265			dir := s.dir
266			s.Close()
267			s2, err := Open(dir)
268			if err != nil {
269				t.Fatalf("claim-time failure must reopen: %v", err)
270			}
271			defer s2.Close()
272			cv2 := mustGetCampaign(s2, spec.ID)
273			if findDevice(cv2, "d1").Status != DeviceFailed || len(cv2.Results) != 1 {
274				t.Fatalf("restored failure view: %+v", cv2)
275			}
276			// 失败原因矛盾也必须被拒绝。
277			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
278				resultDocs(doc, "cmp-1")[0]["reason"] = "other reason"
279			})
280			assertReopenCorrupt(t, dir, original)
281		})
282	
283		t.Run("download claimed unfinished timeout", func(t *testing.T) {
284			// 已领取但未完成的下载在截止时超时：没有结果，也不应有历史。
285			s := setupUpgrade(t, "d1")
286			spec := upSpec()
287			spec.Devices = []string{"d1"}
288			createCampaign(t, s, spec)
289			bringOnline(t, s, "d1")
290			if _, err := s.Claim(spec.ID, "d1", upBase); err != nil {
291				t.Fatal(err)
292			}
293			if err := s.AdvanceCampaign(spec.ID, spec.Deadline); err != nil {
294				t.Fatal(err)
295			}
296			dir := s.dir
297			s.Close()
298			s2, err := Open(dir)
299			if err != nil {
300				t.Fatalf("timeout without results must reopen: %v", err)
301			}
302			defer s2.Close()
303			cv := mustGetCampaign(s2, spec.ID)
304			if findDevice(cv, "d1").Status != DeviceTimeout || len(cv.Results) != 0 {
305				t.Fatalf("restored timeout view: %+v", cv.Results)
306			}
307		})
308	
309		t.Run("later batch skipped has no history", func(t *testing.T) {
310			// 前一批失败后，后续批次未执行：不为其凭空产生结果历史。
311			s := setupUpgrade(t, "d1", "d2")
312			spec := upSpec()
313			spec.BatchSize = 1
314			spec.Devices = []string{"d1", "d2"}
315			createCampaign(t, s, spec)
316			bringOnline(t, s, "d1")
317			// d1 在首次领取前变成不兼容版本，下载失败并使 d2 记为 skipped。
318			if err := s.Report("d1", 2, upBase.Add(-30*time.Second), "v3", json.RawMessage(`{}`)); err != nil {
319				t.Fatal(err)
320			}
321			if _, err := s.Claim(spec.ID, "d1", upBase); !errors.Is(err, ErrIncompatibleVersion) {
322				t.Fatalf("want incompatible, got %v", err)
323			}
324			dir := s.dir
325			s.Close()
326			s2, err := Open(dir)
327			if err != nil {
328				t.Fatalf("skipped batch state must reopen: %v", err)
329			}
330			defer s2.Close()
331			cv := mustGetCampaign(s2, spec.ID)
332			if findDevice(cv, "d2").Status != DeviceSkipped || len(cv.Results) != 1 {
333				t.Fatalf("restored skipped view: %+v", cv.Results)
334			}
335		})
336	}
