303			if d := findDevice(newC, "d1"); d.Status != DeviceDownloading || d.Phase != StageDownload {
304				t.Fatalf("new campaign progress lost: %+v", d)
305			}
306			if len(newC.Results) != 0 {
307				t.Fatalf("claimed unfinished download must have no history: %+v", newC.Results)
308			}
309			w, err := s2.GetDeviceWork("d1")
310			if err != nil {
311				t.Fatal(err)
312			}
313			if w.CampaignID != "cmp-2" || w.Pending == nil {
314				t.Fatalf("work must point to cmp-2 pending op: %+v", w)
315			}
316			if w.Pending.Kind != StageDownload ||
317				w.Pending.ID != encodeOperationIDV2(0, "cmp-2", "d1", StageDownload) ||
318				!w.PendingClaimed {
319				t.Fatalf("claimed download not restored as saved: %+v", w)
320			}
321			if wantWork.Pending == nil ||
322				w.Pending.ID != wantWork.Pending.ID ||
323				w.Pending.Kind != wantWork.Pending.Kind ||
324				w.PendingClaimed != wantWork.PendingClaimed {
325				t.Fatalf("pending work differs from saved state: %+v vs %+v", w, wantWork)
326			}
327		})
328	}
329	
330	// TestRestoreMultipleActiveCampaignsDisjointDevices 多项未结束活动使用互不重叠
331	// 的设备集合时属于合法数据，必须一同正常打开，各设备待办仍指向各自的活动。
332	func TestRestoreMultipleActiveCampaignsDisjointDevices(t *testing.T) {
333		s := setupUpgrade(t, "d1", "d2", "d3")
334		spec1 := activeCampaignSpec("cmp-1", upBase, []string{"d1"}, 1)
335		createCampaign(t, s, spec1)
336		bringOnline(t, s, "d1")
