99		// 合法重发：仅空白/字段顺序/数字等值写法不同，仍按重复上报成功。
100		if err := s.Report("dev-1", 1, base, "1.1", json.RawMessage(`{ "mode": "auto" }`)); err != nil {
101			t.Fatalf("legal whitespace replay: %v", err)
102		}
103		v, _ := s.Get("dev-1")
104		if v.LastSeq != 1 || string(v.Reported) != `{"mode":"auto"}` {
105			t.Fatalf("legal replay altered state: %+v", v)
106		}
107	}
