109	// 普通上报收到顶层数组、null、空输入或尾随内容，均返回 ErrInvalidConfig 且不改状态。
110	func TestReportInvalidConfigShapes(t *testing.T) {
111		s, _ := openTemp(t)
112		mustRegister(t, s, "dev-1", "1.0")
113		for _, cfg := range []string{`[]`, `null`, ``, `{"a":1} null`} {
114			if err := s.Report("dev-1", 1, base, "1.0", json.RawMessage(cfg)); !errors.Is(err, ErrInvalidConfig) {
115				t.Fatalf("config %q: got %v", cfg, err)
116			}
117		}
118		v, _ := s.Get("dev-1")
119		if v.LastSeq != 0 || v.Online || string(v.Reported) != "{}" {
120			t.Fatalf("state changed: %+v", v)
121		}
