128	// 已成功的批量请求用追加尾随内容的配置重发：返回 ErrInvalidConfig，
129	// 首次记录保留、不新增修订号与审计，请求标识仍可查到首次结果。
130	func TestBatchReplayWithTrailingConfig(t *testing.T) {
131		s, _ := openTemp(t)
132		mustRegister(t, s, "dev-1", "1.0")
133		mustRegister(t, s, "dev-2", "1.0")
134		first := mustBatch(t, s, "req-1", "alice", base, []BatchDevice{
135			{DeviceID: "dev-1", Revision: 0, Config: json.RawMessage(`{"a":1}`)},
136			{DeviceID: "dev-2", Revision: 0, Config: json.RawMessage(`{"b":2}`)},
137		})
138	
139		_, err := s.BatchUpdateDesired("req-1", "alice", base, []BatchDevice{
140			{DeviceID: "dev-1", Revision: 0, Config: json.RawMessage(`{"a":1} null`)},
141			{DeviceID: "dev-2", Revision: 0, Config: json.RawMessage(`{"b":2}`)},
142		})
143		if !errors.Is(err, ErrInvalidConfig) {
144			t.Fatalf("invalid replay: got %v, want ErrInvalidConfig", err)
145		}
146	
147		got, err := s.GetBatchRequest("req-1")
148		if err != nil {
149			t.Fatalf("first record lost: %v", err)
150		}
151		if got.Revisions["dev-1"] != first.Revisions["dev-1"] || got.Revisions["dev-2"] != first.Revisions["dev-2"] {
152			t.Fatalf("first record altered: %+v vs %+v", got.Revisions, first.Revisions)
153		}
154		for _, id := range []string{"dev-1", "dev-2"} {
155			v, _ := s.Get(id)
156			if v.Revision != 1 {
157				t.Fatalf("%s revision bumped by rejected replay: %d", id, v.Revision)
158			}
159			if recs, _ := s.Audit(id); len(recs) != 1 {
160				t.Fatalf("%s audit altered: %v", id, recs)
161			}
162		}
163	
164		// 合法重发（换序、空白、等值数字）仍返回首次结果。
165		replay := mustBatch(t, s, "req-1", "alice", base, []BatchDevice{
166			{DeviceID: "dev-2", Revision: 0, Config: json.RawMessage(`{ "b": 2.0 }`)},
167			{DeviceID: "dev-1", Revision: 0, Config: json.RawMessage(`{"a":1.0}`)},
168		})
169		if replay.Revisions["dev-1"] != 1 || replay.Revisions["dev-2"] != 1 {
170			t.Fatalf("legal replay changed revisions: %+v", replay.Revisions)
171		}
172	}
