224	// 首次提交的安装成功结果附带尾随内容：返回 ErrInvalidReport，
225	// 不等到保存阶段，影子、活动进度与结果历史均不变；修正为合法配置后可正常成功。
226	func TestInstallSuccessTrailingConfigFirstTime(t *testing.T) {
227		s := setupUpgrade(t, "d1")
228		spec := upSpec()
