235		cv0, _ := s.GetCampaign(spec.ID)
236		nResults := len(cv0.Results)
237	
238		for _, cfg := range []string{`{"ok":true} null`, `{"ok":true} {}`, `{"ok":true}x`} {
239			err := s.SubmitResult(OperationResult{
240				CampaignID: spec.ID, DeviceID: "d1", OperationID: in,
241				At: upBase.Add(5 * time.Minute), Success: true,
242				Seq: 2, Version: "v2", Config: json.RawMessage(cfg),
243			})
244			if !errors.Is(err, ErrInvalidReport) {
245				t.Fatalf("config %q: got %v, want ErrInvalidReport", cfg, err)
246			}
247		}
248		v, _ := s.GetCampaign(spec.ID)
249		if st := deviceStatus(v, "d1"); st != DeviceInstalling {
250			t.Fatalf("device advanced on invalid report: %s", st)
251		}
252		if len(v.Results) != nResults {
