254		}
255		after, _ := s.Get("d1")
256		if after.Version != shadowBefore.Version || after.LastSeq != shadowBefore.LastSeq {
257			t.Fatalf("shadow changed on invalid report: %+v vs %+v", shadowBefore, after)
258		}
259	
260		// 合法配置随后仍可成功。
261		if err := s.SubmitResult(OperationResult{
262			CampaignID: spec.ID, DeviceID: "d1", OperationID: in,
