270	// 已接受的安装成功结果重发时追加非空白内容：返回 ErrResultConflict，
271	// 已接受结果保留；合法重发即使设备后来上报更大序号、活动已结束也继续成功。
272	func TestInstallSuccessReplayTrailingConflicts(t *testing.T) {
