// 一台设备的计时记录损坏即拒绝打开整个存储，其他设备再正常也不可只跳过坏设备。
func TestRestoreDiffSinceOneBadDeviceRejectsAll(t *testing.T) {
	doc := diffSinceDoc() // dev-1 合法
	doc.Devices["good"] = fixState{
		Version:  "1.0",
